"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[383],{4106(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"pixelstormSidebar":[{"type":"link","href":"/website/docs/","label":"PixelStorm API Docs","docId":"index","unlisted":false},{"type":"category","label":"Getting Started","items":[{"type":"link","href":"/website/docs/getting-started","label":"Getting Started","docId":"getting-started","unlisted":false},{"type":"link","href":"/website/docs/quick-start","label":"Quick Start Guide","docId":"quick-start","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","href":"/website/docs/core","label":"Core","docId":"core","unlisted":false},{"type":"link","href":"/website/docs/window-application","label":"Window / Application","docId":"window-application","unlisted":false},{"type":"link","href":"/website/docs/input","label":"Input","docId":"input","unlisted":false},{"type":"link","href":"/website/docs/ecs-entities","label":"ECS / Entities","docId":"ecs-entities","unlisted":false},{"type":"link","href":"/website/docs/world-helpers","label":"World Helpers","docId":"world-helpers","unlisted":false},{"type":"link","href":"/website/docs/components","label":"Components","docId":"components","unlisted":false},{"type":"link","href":"/website/docs/camera","label":"Camera","docId":"camera","unlisted":false},{"type":"link","href":"/website/docs/rendering","label":"Rendering","docId":"rendering","unlisted":false},{"type":"link","href":"/website/docs/scenes","label":"Scenes","docId":"scenes","unlisted":false},{"type":"link","href":"/website/docs/physics","label":"Physics","docId":"physics","unlisted":false},{"type":"link","href":"/website/docs/animation","label":"Animation","docId":"animation","unlisted":false},{"type":"link","href":"/website/docs/particles","label":"Particles","docId":"particles","unlisted":false},{"type":"link","href":"/website/docs/text-ui","label":"Text / UI","docId":"text-ui","unlisted":false},{"type":"link","href":"/website/docs/examples","label":"Examples","docId":"examples","unlisted":false},{"type":"link","href":"/website/docs/faq","label":"FAQ / Common Pitfalls","docId":"faq","unlisted":false}]},"docs":{"animation":{"id":"animation","title":"Animation","description":"The engine animation system is based on spritesheet clips and one animator per entity. It is intentionally simple, but it covers the common cases needed by a small 2D game: idle states, walking loops, one-shot effects, and basic clip switching.","sidebar":"pixelstormSidebar"},"camera":{"id":"camera","title":"Camera","description":"PixelStorm uses a 2D orthographic camera. That choice fits the engine well because it keeps the projection simple, makes pixel-art scenes easier to reason about, and lines up naturally with the logical resolution used by the rest of the API.","sidebar":"pixelstormSidebar"},"components":{"id":"components","title":"Components","description":"These are the data components you will use most often from gameplay code. They are intentionally small and data-oriented so the systems can read exactly what they need.","sidebar":"pixelstormSidebar"},"core":{"id":"core","title":"Core","description":"The core module groups the utility types and services that appear throughout the engine:","sidebar":"pixelstormSidebar"},"ecs-entities":{"id":"ecs-entities","title":"ECS / Entities","description":"PixelStorm exposes a public ECS layer, but gameplay code normally works through World and Entity. That keeps the API readable while still leaving the registry available for lower-level use cases.","sidebar":"pixelstormSidebar"},"examples":{"id":"examples","title":"Examples","description":"These patterns come from the demo and from the real public API. They are meant to show the shape of normal gameplay code, not to replace the full reference pages.","sidebar":"pixelstormSidebar"},"faq":{"id":"faq","title":"FAQ / Common Pitfalls","description":"Nothing appears on screen","sidebar":"pixelstormSidebar"},"getting-started":{"id":"getting-started","title":"Getting Started","description":"PixelStorm is designed so a simple scene can be running with very little boilerplate. The core idea is straightforward:","sidebar":"pixelstormSidebar"},"index":{"id":"index","title":"PixelStorm API Docs","description":"PixelStorm is a compact 2D engine written in C++ and built around OpenGL. It was designed for pixel-art style games, so the public API focuses on clear gameplay concepts: scenes, entities, resources, input, camera control, 2D rendering, physics, animation, particles, and text.","sidebar":"pixelstormSidebar"},"input":{"id":"input","title":"Input","description":"Input handles keys, mouse, named actions, and axes. It is snapshot-based, which means gameplay code reads the state captured for the current frame instead of polling the operating system directly.","sidebar":"pixelstormSidebar"},"particles":{"id":"particles","title":"Particles","description":"PixelStorm\'s particle system creates lightweight entities for visual effects. The implementation is simple on purpose: particles are just engine entities with their own transform, sprite, and particle state.","sidebar":"pixelstormSidebar"},"physics":{"id":"physics","title":"Physics","description":"PixelStorm exposes AABB physics, gravity, and triggers. The system is deliberately simple, but it is enough to support movement, obstacle blocking, and scene interaction for a 2D game.","sidebar":"pixelstormSidebar"},"quick-start":{"id":"quick-start","title":"Quick Start Guide","description":"The fastest way to see PixelStorm in action is to create a small scene that spawns one sprite, moves it with input, and draws a bit of UI text.","sidebar":"pixelstormSidebar"},"rendering":{"id":"rendering","title":"Rendering","description":"Rendering in PixelStorm is intentionally small and focused on 2D. The engine draws quads, text, and debug outlines; the gameplay side works with textures, fonts, and logical resource names; and the final image can optionally go through a CRT-style screen pass.","sidebar":"pixelstormSidebar"},"scenes":{"id":"scenes","title":"Scenes","description":"Scenes are the main gameplay flow unit in PixelStorm. They let the engine separate menu states, game states, and transition states without forcing everything into a single update function.","sidebar":"pixelstormSidebar"},"text-ui":{"id":"text-ui","title":"Text / UI","description":"PixelStorm gives you two paths for drawing text:","sidebar":"pixelstormSidebar"},"window-application":{"id":"window-application","title":"Window / Application","description":"This page covers the main runtime object and the window layer that supports it. In practice, gameplay code normally works through Application, while Window stays as the lower-level runtime wrapper around GLFW and the OpenGL context.","sidebar":"pixelstormSidebar"},"world-helpers":{"id":"world-helpers","title":"World Helpers","description":"World is the recommended way to create entities from gameplay code. Instead of assembling every component manually, the helper methods create a useful starting point for the kind of object you want to build.","sidebar":"pixelstormSidebar"}}}}')}}]);